//! Mordred parity test.
//!
//! Compares FerrumChem against all 1613 2D descriptors of mordred-community
//! 2.0.7 (`tests/data/mordred_parity_reference.csv`, generated by
//! `scripts/generate_mordred_reference.py`). Mordred names are mapped onto
//! FerrumChem columns with `ferrum_core::desc::mordred_names::ferrum_column`
//! (aliases and `Mordred_`-prefixed variants); columns FerrumChem does not
//! implement yet are listed, not failed. Values Mordred reports as missing are
//! stored as `nan` and must be NaN in FerrumChem too. Mechanics and baseline
//! handling are the same as in `rdkit_parity.rs`; known deviations are tracked
//! in `tests/data/mordred_parity_baseline.tsv`.
//!
//! ```text
//! FERRUM_UPDATE_PARITY_BASELINE=1 cargo test -p ferrum_core --release --test mordred_parity
//! FERRUM_PARITY_VERBOSE=1 cargo test -p ferrum_core --release --test mordred_parity -- --nocapture
//! ```

mod common;

use ferrum_core::desc::mordred_names::ferrum_column;

#[test]
fn mordred_parity() {
    common::parity::run_parity_mapped(
        "Mordred",
        "mordred_parity_reference.csv",
        "mordred_parity_baseline.tsv",
        &ferrum_column,
    );
}
